const h=require("http"),f=require("fs"),p=require("path");
const R=process.cwd(),P=+process.env.PORT||8777;
const T={".html":"text/html; charset=utf-8",".css":"text/css; charset=utf-8",".js":"text/javascript; charset=utf-8",".mjs":"text/javascript; charset=utf-8",".json":"application/json",".svg":"image/svg+xml",".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".gif":"image/gif",".webp":"image/webp",".ico":"image/x-icon",".pdf":"application/pdf",".txt":"text/plain; charset=utf-8",".xml":"application/xml",".woff2":"font/woff2",".mp4":"video/mp4",".patch":"text/plain"};
h.createServer((q,s)=>{
  const x=p.join(R,decodeURIComponent(q.url.split("?")[0]));
  if(!x.startsWith(R)){s.writeHead(403);return s.end();}
  const t=(g,sinon)=>f.stat(g,(e,st)=>{
    if(!e&&st.isDirectory())return t(p.join(g,"index.html"),sinon);
    if(e||!st.isFile()){if(sinon)return sinon();s.writeHead(404,{"Content-Type":"text/plain"});return s.end("404");}
    s.writeHead(200,{"Content-Type":T[p.extname(g).toLowerCase()]||"application/octet-stream","Content-Length":st.size,"Cache-Control":"no-store, must-revalidate"});
    f.createReadStream(g).pipe(s);
  });
  t(x,p.extname(x)?null:()=>t(x+".html"));
}).listen(P);
